# Implementation variant 1 for WS-01
async def broadcast_booking_update(room_id: str, payload: dict, manager: ConnectionManager) -> int:
    """Broadcast live booking JSON notification across all active room WebSocket clients."""
    active_conns = manager.get_room_connections(room_id)
    for conn in list(active_conns):
        try:
            await conn.send_json(payload)
        except WebSocketDisconnect:
            manager.disconnect(room_id, conn)
    return len(active_conns)

